package com.deepanshuraj.opspilot.domain;
import java.time.*; import org.springframework.boot.*; import org.springframework.stereotype.Component;
@Component public class OpsDataLoader implements ApplicationRunner { private final OrderRepository orders; private final WorkflowRunRepository workflows; public OpsDataLoader(OrderRepository o,WorkflowRunRepository w){orders=o;workflows=w;}
 public void run(ApplicationArguments a){if(orders.count()>0)return; Instant now=Instant.now(); seed("ORD-1001","Northwind Retail","Broadband 1Gbps","NCR","IN_PROGRESS","PROVISION_ACCESS","STUCK",2,"Downstream provisioning callback not received within SLA (timeout on ACCESS adapter).",now); seed("ORD-1002","Acme Health","Managed Voice","West","IN_PROGRESS","SEND_NOTIFICATION","FAILED",3,"Notification publish rejected: EventBus 5xx from CloudSense endpoint.",now.minusSeconds(60)); seed("ORD-1003","Globex Bank","SD-WAN Link","South","COMPLETED","COMPLETE_ORDER","COMPLETED",1,null,now.minusSeconds(120)); seed("ORD-1004","Initech Pay","Device Dispatch","NCR","IN_PROGRESS","DISPATCH_DEVICE","RUNNING",1,null,now.minusSeconds(180)); seed("ORD-1005","Umbrella Care","Broadband 500Mbps","East","CANCELLED","CANCEL_ORDER","COMPLETED",1,null,now.minusSeconds(240)); }
 private void seed(String id,String c,String p,String r,String s,String step,String state,int attempts,String reason,Instant at){orders.save(new CustomerOrder(id,c,p,r,s,at));workflows.save(new WorkflowRun(id,step,state,attempts,reason,at));}}
